function ActionDarkDreamMainDialog:RefreshAllRedPoint()
    local dojo = self:GetHomeDojo()
    local isHaveRedPoint = false
    if not isNull(dojo) then
        local groups = dojo:GetGroups()
        for i , v in pairs(groups) do
            local tempRed = ChaoticRecallUtils.IsGroupHaveRedPoint(v.groupId,i)
            if tempRed then
