function ActionDarkDreamMainDialog:InitBtnList()
    local dojo = self:GetHomeDojo()
    if not isNull(dojo) then
        local groups = dojo:GetGroups()
        for i , v in pairs(groups) do
            local vo = ChaoticRecallUtils.GetChaoticRecallTagVo(v.groupId)
            local tempGo = vo.groupType == 0 and self.Cell.gameObject or self.SpecialCell.gameObject
            local cellGo = CS.UnityEngine.GameObject.Instantiate(tempGo.gameObject)
            if not isNull(cellGo) then
                KTool.SetParent(cellGo,self.BtnList.gameObject,false)
                local cellEnv = CfUtils.GetLuaScr(cellGo,BtnCellPath)
                if not isNull(cellEnv) then
                    table.insert(self.btnEnv,cellEnv)
                    cellEnv:SetCallBackAndIndex(Bind(self,self.OnBtnCellClick),i)
                    cellEnv:PlayHideAni()
                    cellEnv:RefreshShow(v, self.selectIndex, vo, table.count(groups))
                end
                CfUtils.SetActive(cellGo.gameObject, true)
            end
        end

        for i, v in pairs(self.btnEnv) do
            v:PlayShowAni()
        end
    end
end

function ActionDarkDreamMainDialog:IsGroupUnLock(vo)
    if checkNumber(vo.condition) == 0 then
        return true
    else
        local nodeVo = ChaoticRecallUtils.GetChaoticRecallNodeVo(vo.condition)
        local isUnLock = ChaoticRecallUtils.GetIsPassById(nodeVo.groupId,vo.condition)
        return isUnLock
    end
    return true
end

---是否解锁了困难
function ActionDarkDreamMainDialog:IsHardGroupUnLock()
    local dojo = self:GetHomeDojo()
    if not isNull(dojo) then
        local groups = dojo:GetGroups()
        for i = #groups, 1, -1  do
            if checkNumber(groups[i].groupId) > 100 then
                local vo = ChaoticRecallUtils.GetChaoticRecallTagVo(groups[i].groupId)
                if not isNull(vo) then
                    local isUnLock = self:IsGroupUnLock(vo)
                    if isUnLock then
                        return true,i
                    end
                end
            end
        end
    end
    return false,1
end

