    CfUtils.CookieSave("ActionDarkDreamMainDialogGroupIdAndIndex",table.concat({self.groupId,"_",self.curIndex}))
    self.btnEnv[self.curIndex]:Select()
    self:RefreshBgAndTitle(groupId)
    ---@type ChaoticRecallDojo
    local dojo = self:GetHomeDojo()
    self.curNodeData = dojo:GetNodeData(self.curIndex)
    self:InitShareBtn()
    
    if vo.groupType == 0 then
        local data = dojo:GetUpGroupData(self.curIndex)
        self:RefreshUpGroup(data)
        self:RefreshLoopListView()
        self:RefreshActionBtnRecommend()
        self:RefreshProgressReward(vo, dojo)
        self:RefreshRewardStatus(dojo)
    else
        self:RefreshChallengeShow(dojo)
        self:RefreshRewardStatus(dojo, true)
    end
    
    self:RefreshProgressRedPoint()
    self:RefreshRewardRedPoint()
    local aniName = "ActionDarkDreamMainDialog_RedGo"
    CfUtils.PlayAnimation(self.controller,aniName)
    
    if isNull(self.curIndex) then
        local nodeIndex = self:GetClickNodeIndex()
        self.controller:SetExtraArgument(table.concat({index,"_",nodeIndex}))
    else
        self.controller:SetExtraArgument(table.concat({index,"_",0}))
    end
end

