function ActionDarkDreamMainDialog:RefreshProgressReward(vo, dojo)
    CfUtils.SetActive(self.Progress,table.count(vo.rewards) > 0)
    if table.count(vo.rewards) > 0 then
        local total = 0
        local progress = 0
        for i, v in pairs(self.curNodeData) do
            for j, node in ipairs(v) do
                total = total + 1
                if node.passed == 1 then
                    progress = progress + 1
                end
            end
        end
        self.Slider.value = progress/total
        CfUtils.FillText(self.TextNumber,progress.."/"..total)
        local isGet = dojo:IsGetProgressReward(self.curIndex)
        CfUtils.SetUISwitchImage(self.ImgIcon,isGet and 2 or 1)
        if progress == total and not isGet then
            CfUtils.PlayAnimation(self.AniRoot,"ActionDarkDreamMainDialog_BtnRewardActivate")
        else
            CfUtils.PlayAnimation(self.AniRoot,"ActionDarkDreamMainDialog_BtnRewardDefault")
        end
    end
end

