function ActionDarkDreamMainDialog:InitShareBtn()
    local isOpen = false
    for i, v in pairs(self.curNodeData) do
        for k, j in pairs(v) do
            if j.passed == 1 then
                isOpen = true
                break
            end
        end
        if isOpen then
            break
        end
    end
    KTool.SetActive(self.BtnShare.gameObject,isOpen)
    if isOpen then
        GameUtils.InstallShareButton(self.BtnShare, Constants.ShareType.DARK_DREAM, 'Prefabs/Share/ActionDarkDreamResultShareShowDialog.prefab',nil,true)
    end
end

function ActionDarkDreamMainDialog:GetClickNodeIndex()
    local nodeIndex = 0
    local groupIndex = 0
    if not isNull(self.controller.Argument.extra) then
        local str = string.split(self.controller.Argument.extra,"_")
        groupIndex = checkNumber(str[1])
        nodeIndex = checkNumber(str[2])
    end

    if nodeIndex == 0 then
        nodeIndex = 1
    end

    if groupIndex == 0 then
        groupIndex = 1
    end

    return nodeIndex,groupIndex
end

function ActionDarkDreamMainDialog:RefreshRewardStatus(dojo, isSpecial)
    local nodes = checkTable(dojo:GetAllNodes(self.curIndex))
    local totalStar = isSpecial and (table.count(nodes) - 1) * 3 or table.count(nodes) * 3
    local passStar = dojo:GetAllPassStar(self.curIndex)
    CfUtils.FillText(self.TxtNum,string.format("<color=#FFFFFF><size=38>%s</size></color>/%s",passStar,totalStar))
end

function ActionDarkDreamMainDialog:RefreshRewardRedPoint()
    local groupId = self.groupId
    if isNull(groupId) then
        local dojo = self:GetHomeDojo()
        groupId = dojo:GetGroupId(self.curIndex)
    end
    local isHaveRedPoint = ChaoticRecallUtils.IsHaveStarRedPoint(groupId,self.curIndex)
    local redGo = GameUtils.GetRedPointGo(self.BtnReward)
    if not isNull(redGo) then
        KTool.SetActive(redGo,isHaveRedPoint)
        KTool.SetActive(self.UIFX_RewardGlow,isHaveRedPoint)
    end
    KTool.SetActive(self.BtnReward.gameObject,true)
end

