function ActionDarkDreamMainDialog:RefreshBgAndTitle(groupId)
    local vo = ChaoticRecallUtils.GetChaoticRecallTagVo(groupId)
    if not isNull(vo) then
        CfUtils.FillImage(self.Bg,vo.background)
        CfUtils.FillText(self.TxtTitle,vo.name)
        KTool.SetActive(self.TimeGroup,checkNumber(groupId) >= 100)
        if checkNumber(groupId) >= 100 then
            local dojo = self:GetHomeDojo()
            local leftTime = dojo:GetRemainTime()
            local time = CfUtils.GetTimeHMS11(leftTime)
            local str = table.concat({localize("剩余时间："),time})
            CfUtils.FillText(self.TxtTime,str)
        end

        local title = vo.title
        if not isNull(title) and title ~= "" then
            CfUtils.FillText(self.TxtLv,vo.title)
            CfUtils.SetActive(self.TxtLv.gameObject,true)
        else
            CfUtils.SetActive(self.TxtLv.gameObject,false)
        end

    end
end

function ActionDarkDreamMainDialog:RefreshLoopListView()
    local index = self:GetScrollIndex()
    if self.LevelRootScrollView then
        if not self.LevelRootScrollView.IsListViewInit then
            self.LevelRootScrollView:InitListView(#self.curNodeData, Bind(self, self.OnRefreshCellIndex))
            self.LevelRootScrollView:UpdateDisplayItemCount("Cell")
            self.LevelRootScrollView:MovePanelToItemIndex(index - 1,0)
        else
            GameUtils.ReloadData(self.LevelRootScrollView, #self.curNodeData)
            self.LevelRootScrollView:MovePanelToItemIndex(index - 1,0)
        end
    end
end

function ActionDarkDreamMainDialog:GetScrollIndex()
    if not isNull(self.controller.Argument.extra) then
        local nodeIndex, groupIndex = self:GetClickNodeIndex()
        if groupIndex == self.curIndex then
            return checkNumber(nodeIndex)
        end
    end
    local isHaveSkipLevel , isHavePassedLevel ,skipIndex , noPassedIndex
    isHaveSkipLevel, isHavePassedLevel, skipIndex, noPassedIndex = self:IsHaveSkipLevelAndPassedLevel()
    ---当有跳转关卡  并且没有过通关记录时 要定位到跳转关卡 否则就定位到通关关卡的下一关
    if isHaveSkipLevel and not isHavePassedLevel then
        return skipIndex
    else
        if isNull(noPassedIndex) then
            return table.count(self.curNodeData)
        end
        return noPassedIndex
    end
end

function ActionDarkDreamMainDialog:GetIsSkipLevel(nodeId)
    local vo = ChaoticRecallUtils.GetChaoticRecallTagVo(self.groupId)
    return checkNumber(vo.skipLevel) == nodeId
end

function ActionDarkDreamMainDialog:IsHaveSkipLevelAndPassedLevel()
    local isHavePassLevel = false
    local isHaveSkipLevel = false
    local skipIndex = 1
    local noPassedIndex = nil
    for i, v in pairs(self.curNodeData) do
        for k, j in pairs(v) do
            local isSkipLevel = self:GetIsSkipLevel(j.nodeId)
            if isSkipLevel then
                isHaveSkipLevel = true
                skipIndex = i
            end
            if j.passed == 1 then
                isHavePassLevel = true
            end

            if j.passed == 0 and isNull(noPassedIndex) then
                noPassedIndex = i
            end
        end
    end
    return isHaveSkipLevel,isHavePassLevel,skipIndex,noPassedIndex
end

function ActionDarkDreamMainDialog:OnRefreshCellIndex(listView,index)
    if index < 0 or index >= #self.curNodeData then
        return
    end

    local cell = listView:NewListViewItem("Cell")
    if not isNull(cell) then
        local tableCellEnv = CfUtils.GetLuaScr(cell, CellPath)
        if not isNull(tableCellEnv) then
            local index = index + 1
            local isLast = #self.curNodeData == index
            local isRed = checkNumber(self.groupId) > 100
            tableCellEnv:RefreshShow(self.curNodeData[index],isLast,function()
                self.controller:SetExtraArgument(table.concat({self.curIndex,"_",index}))
            end,self.groupId,isRed)
            tableCellEnv:PlayHideAni()
            if listView.DisplayItemNumber < listView.DisplayItemCount then
                tableCellEnv:PlayShowAni(listView.DisplayItemNumber)
                listView.DisplayItemNumber = listView.DisplayItemNumber + 1
            else
                tableCellEnv:PlayIdleAni()
            end

        end
    end
    return cell
end

