function ActionDarkDreamMainDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            local preRewards = ChaoticRecallUtils.GetChaoticRecallMgr():GetPreRewards() or {}
            if table.count(preRewards) > 0 then
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = preRewards,isJumpOff = true } })
                ChaoticRecallUtils.GetChaoticRecallMgr():CleanPreReward()
            end
        end)
    end))
    return coWait
end

function ActionDarkDreamMainDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            GameUtils.Request(Interfaces.OverseaNightmareQuest,{},function(request,response)
                if response.errCode == 0 then
                    local data = response.data
                    ChaoticRecallUtils.GetChaoticRecallMgr():UpdateHomeDojo(data)
                    self:SetNormalSelectIndex()
                    self:RefreshShow()
                end
            end)
        end)
    end))
    return coWait
end

function ActionDarkDreamMainDialog:SetNormalSelectIndex()
    local isUnLock,unLockIndex = self:IsHardGroupUnLock()
    self.selectIndex = isUnLock and unLockIndex or 1
    local index
    if not isNull(self.controller.Argument) and not isNull(self.controller.Argument.extra) then
        local str = self.controller.Argument.extra
        local numS = string.split(str,"_")
        index = numS[1]
    end
    if not isNull(index) then
        self.selectIndex = checkInt(index)
    end
end

function ActionDarkDreamMainDialog:RefreshShow()
    self:InitBtnList()
    self:RefreshAllRedPoint()
end

function ActionDarkDreamMainDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
            self:RemoveEventListener()
            self:Delete()
            self = nil --lua层的gc需要    
        end)
    end))
    return coWait
end

function ActionDarkDreamMainDialog:OnBtnRewardClick()
    UIModule.OpenDialog({ id = Constants.UITypeIds.ActionDarkDreamRewardPopup, parameters = { index = self.curIndex } })
end

function ActionDarkDreamMainDialog:OnBtnSupplyClick()
    local WelfareConstants = import('Game.UI.Welfare.WelfareConstants')
    CfUtils.DialogOpen(Constants.UITypeIds.UIWelfareMainDialog, {selectedIndex = WelfareConstants.OpenIds.NightmarePassCard}, CfUtils.DialogGetAllArgs())
end

function ActionDarkDreamMainDialog:OnBtnProgressRewardClick()
    local isHave = ChaoticRecallUtils.IsHaveProgressReward(self.groupId, self.curIndex)
    if isHave then
        local vo = ChaoticRecallUtils.GetChaoticRecallTagVo(self.groupId)
        local dojo = self:GetHomeDojo()
        GameUtils.Request(Interfaces.OverseaNightDrawAllPassReward,{groupId = self.groupId},function(request,response)
            if checkNumber(response.errCode) == 0 then
                dojo:UpdateProgressGetState(self.curIndex, 1)
                if table.count(response.data.rewards) > 0 then
                    GoodsUtils.DrawRewards(response.data.rewards)
                    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = {
                        rewards = response.data.rewards,} })
                end
                self:RefreshProgressReward(vo, dojo)
                self:RefreshProgressRedPoint()
            end
        end)
    else
        local isGet = self:GetHomeDojo():IsGetProgressReward(self.curIndex)
        if isGet then
            GameUtils.Toast(localize("奖励已领取"))
        else
            GameUtils.Toast(localize("通关当前所有关卡可领取"))
        end
    end
end

function ActionDarkDreamMainDialog:GetChallengeNodeEnv()
    if isNull(self.challengeEnv) then
        self.challengeEnv = CfUtils.GetLuaScr(self.NewFunction.gameObject,ChallengeNodePath)
    end
    return self.challengeEnv
end

return ActionDarkDreamMainDialog